import{_ as t,a as r,o as a,a4 as o}from"./chunks/framework.-FZumj2l.js";const p=JSON.parse('{"title":"Returns (RMA)","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/shop/returns/index.md","filePath":"api/graphql-api/shop/returns/index.md","lastUpdated":1784902076000}'),n={name:"api/graphql-api/shop/returns/index.md"};function s(d,e,i,u,h,l){return a(),r("div",null,e[0]||(e[0]=[o('<h1 id="returns-rma" tabindex="-1">Returns (RMA) <a class="header-anchor" href="#returns-rma" aria-label="Permalink to &quot;Returns (RMA)&quot;">​</a></h1><p>Returns — also called RMA (Return Merchandise Authorization) — let a logged-in customer ask the store to take back or cancel an item they ordered. A customer can raise a return for an eligible item, converse with the store about it through a message thread, and cancel, reopen or close the request. Every return is scoped to the customer who owns it; a customer can only ever see and act on their own returns.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>All return endpoints require an authenticated <strong>customer</strong> — provide the storefront key and a customer Bearer token. See the <a href="/api/graphql-api/authentication.html">Authentication</a> page for how to obtain and send them.</p><h2 id="how-a-return-works" tabindex="-1">How a return works <a class="header-anchor" href="#how-a-return-works" aria-label="Permalink to &quot;How a return works&quot;">​</a></h2><ol><li><strong>Find eligible items.</strong> Query <a href="/api/graphql-api/shop/returns/queries/list-returnable-items.html"><code>returnableItems</code></a> for an order to see which items are still within their return window and how many units can be returned or canceled.</li><li><strong>Pick a reason.</strong> Query <a href="/api/graphql-api/shop/returns/queries/list-return-reasons.html"><code>returnReasons</code></a> for the resolution type (<code>return</code> or <code>cancel_items</code>) to get the reason ids to choose from.</li><li><strong>Raise the return.</strong> Call <a href="/api/graphql-api/shop/returns/mutations/create-return.html"><code>createCustomerReturn</code></a> with the order, the item, a quantity, the resolution type and a reason id. The return starts in a <code>Pending</code> status.</li><li><strong>Converse.</strong> Read the thread with <a href="/api/graphql-api/shop/returns/queries/list-return-messages.html"><code>customerReturnMessages</code></a> and add messages with <a href="/api/graphql-api/shop/returns/mutations/send-return-message.html"><code>createCustomerReturnMessage</code></a>.</li><li><strong>Cancel, reopen or close.</strong> Use <a href="/api/graphql-api/shop/returns/mutations/cancel-return.html"><code>cancelCustomerReturn</code></a>, <a href="/api/graphql-api/shop/returns/mutations/reopen-return.html"><code>reopenCustomerReturn</code></a> or <a href="/api/graphql-api/shop/returns/mutations/close-return.html"><code>closeCustomerReturn</code></a> to change the state of the request.</li></ol><h2 id="status-flags" tabindex="-1">Status flags <a class="header-anchor" href="#status-flags" aria-label="Permalink to &quot;Status flags&quot;">​</a></h2><p>Each return carries three action flags that tell a client which operations are currently allowed:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Meaning</th></tr></thead><tbody><tr><td><code>canClose</code></td><td>The return can be closed (marked solved) by the customer.</td></tr><tr><td><code>canReopen</code></td><td>The return can be reopened back to pending.</td></tr><tr><td><code>isExpired</code></td><td>The return is past its allowed action window.</td></tr></tbody></table><p>These flags are populated on the single-return view; on the list they come back <code>null</code>.</p><h2 id="quantity-caps-are-enforced-by-the-store" tabindex="-1">Quantity caps are enforced by the store <a class="header-anchor" href="#quantity-caps-are-enforced-by-the-store" aria-label="Permalink to &quot;Quantity caps are enforced by the store&quot;">​</a></h2><p>When raising a return, the quantity you send is capped server-side by the trusted quantity a customer is actually allowed to return or cancel for that item (<code>forReturnQuantity</code> / <code>forCancelQuantity</code> from <code>returnableItems</code>). You can never return more units than were ordered and are still eligible.</p><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th><th>Description</th></tr></thead><tbody><tr><td>List own returns</td><td><a href="/api/graphql-api/shop/returns/queries/list-returns.html"><code>customerReturns</code></a></td><td>Paginated list of the customer&#39;s own returns.</td></tr><tr><td>View one return</td><td><a href="/api/graphql-api/shop/returns/queries/view-return.html"><code>customerReturn</code></a></td><td>A single return the customer owns.</td></tr><tr><td>List returnable items</td><td><a href="/api/graphql-api/shop/returns/queries/list-returnable-items.html"><code>returnableItems</code></a></td><td>Return-eligible items of one of the customer&#39;s orders.</td></tr><tr><td>List return reasons</td><td><a href="/api/graphql-api/shop/returns/queries/list-return-reasons.html"><code>returnReasons</code></a></td><td>Active reasons for a resolution type.</td></tr><tr><td>List return messages</td><td><a href="/api/graphql-api/shop/returns/queries/list-return-messages.html"><code>customerReturnMessages</code></a></td><td>The conversation thread of a return.</td></tr><tr><td>Raise a return</td><td><a href="/api/graphql-api/shop/returns/mutations/create-return.html"><code>createCustomerReturn</code></a></td><td>Create a new return for one order item.</td></tr><tr><td>Cancel a return</td><td><a href="/api/graphql-api/shop/returns/mutations/cancel-return.html"><code>cancelCustomerReturn</code></a></td><td>Cancel the customer&#39;s own return.</td></tr><tr><td>Reopen a return</td><td><a href="/api/graphql-api/shop/returns/mutations/reopen-return.html"><code>reopenCustomerReturn</code></a></td><td>Reopen a canceled/declined return.</td></tr><tr><td>Close a return</td><td><a href="/api/graphql-api/shop/returns/mutations/close-return.html"><code>closeCustomerReturn</code></a></td><td>Mark a return solved.</td></tr><tr><td>Send a message</td><td><a href="/api/graphql-api/shop/returns/mutations/send-return-message.html"><code>createCustomerReturnMessage</code></a></td><td>Add a message to the return conversation.</td></tr></tbody></table>',14)]))}const m=t(n,[["render",s]]);export{p as __pageData,m as default};
